from typing import List

def find_min_weight_partition(a: List[int], k: int) -> int:
    n = len(a)

    @cache
    def dp(l: int, r: int) -> int:
        if l == r:
            return 0
        return min(a[l] * (r - l + 1) + dp(l + 1, r), a[r] * (r - l + 1) + dp(l, r - 1))

    left = list(range(1, n))
    right = []

    for i in range(n):
        for j in range(i + 1):
            if dp(j, i) < dp(n - 1, i):
                right += [j]
                break
        else:
            right += [n - 1]

    return min(dp(l, r) for (l, r) in zip(left, right))

