def min_cost(dist):
    n = len(dist)
    cost = 0
    x = 0
    for a, b in dist:
        if a == x:
            cost += b
        else:
            cost += -dist[x][a]
            dist[dist[b][x+1]] -= 2
        x += 1
    return cost

class Solution:
