import math

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(math.sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

def minimum_operations_required(n, card_numbers):
    operations = 0
    prime = 3
    while n > 0:
        if is_prime(prime):
            valid_cards = []
            for card in card_numbers:
                if prime >= card:
                    valid_cards.append(card)
            valid_cards = set(valid_cards)
            n -= len(valid_cards)
        else:
            valid_cards = set(card_numbers)
            n -= len(valid_cards)
        operations += 1
        prime = 3
        if operations % 2 == 0:
            prime += prime // 2
        else:
            prime += prime // 4

    return operations

